sys_script_include.script:
function TableCreate(vScope, strName, strLabel, strParentTable)
{
	var strScopeSysId = '';

	var grApp = GetAppRecord(vScope);
	if (IsValidRecord(grApp) == true)
	{
		strScopeSysId = GetStringValue(grApp.sys_id);
	}
	else if (vScope == 'global')
	{
		strScopeSysId = 'global';
	}
	if (IsValidSysId(strScopeSysId) == false)
	{
		return false;
	}

	strName = MakeTableName(grApp,strName);
	if (strName == false)
	{
		return false;
	}

	strLabel = GetStringValue(strLabel);
	if (strLabel == '')
	{
		return false;
	}

	var strParentTableSysId = '';
	strParentTable = GetStringValue(strParentTable);
	if (strParentTable != '')
	{
		if (IsValidTable(strParentTable) == false)
		{
			return false;
		}
		var grParentTable = GetTableRecord(strParentTable);
		if (IsValidRecord(grParentTable) == false)
		{
			return false;
		}
		strParentTableSysId = GetStringValue(grParentTable.sys_id);
	}




	var strTableSysId = RecordInsertOrUpdate(
		'sys_db_object',
		{
			sys_scope: strScopeSysId,
			name: strName
		},
		{
			super_class: strParentTableSysId
		},
		{
			label: strLabel,
			configuration_access: true,
			create_access: true,
			update_access: true,
			delete_access: true
		});

	return strTableSysId;
}
